  monster: string;
  rank?: number;
}

const SPHINX = "sphinx";

const BASE_SCORE_FOR_THREE_TYPES = 1;
const POINT_FOR_THE_SPHINX_ITSELF = 1;

const isSphinx = (card: Card): boolean => card.monster === SPHINX;

const SCORE_PER_SPHINX = BASE_SCORE_FOR_THREE_TYPES + POINT_FOR_THE_SPHINX_ITSELF;

export const scoreArmy = (army: Card[]): number =>
  army.filter(isSphinx).reduce((total) => total + SCORE_PER_SPHINX, 0);

